const CF_VERSION='2026.08.15-create1';
function cfToast(text,type=''){let h=document.querySelector('.toast-host');if(!h){h=document.createElement('div');h.className='toast-host';document.body.appendChild(h)}const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=text;h.appendChild(e);setTimeout(()=>e.remove(),3400)}
function fieldOf(control){return control?.closest('.field')||null}
function ensureHint(form){let hint=form.querySelector('.cf-category-hint');if(!hint){hint=document.createElement('div');hint.className='cf-category-hint demo-note';const cat=form.querySelector('input[name="required_categories"]')?.closest('.field');cat?.appendChild(hint)}return hint}
function hydrateVehicleCreate(form){if(!form||form.dataset.cfPatch)return;form.dataset.cfPatch=CF_VERSION;const type=form.elements.vehicle_class,fuel=form.elements.fuel_type_id,norm=form.elements.fuel_norm,currentFuel=form.elements.current_fuel_l,tank=form.elements.tank_capacity_l;if(!type)return;const fuelField=fieldOf(fuel),normField=fieldOf(norm),currentFuelField=fieldOf(currentFuel),tankField=fieldOf(tank),hint=ensureHint(form);
  function update(){const option=type.selectedOptions?.[0];const trailer=type.value==='trailer';[fuelField,normField,currentFuelField,tankField].forEach(el=>el?.classList.toggle('cf-hidden',trailer));[fuel,norm,currentFuel,tank].forEach(el=>{if(!el)return;el.disabled=trailer;if(trailer)el.value=''});if(fuel)fuel.required=!trailer;if(norm)norm.required=!trailer;const cat=option?.dataset?.cat||'';if(hint){if(trailer){hint.textContent='Для прицепа укажите категорию только если она требуется для его эксплуатации (например BE / CE).'}else if(cat){hint.innerHTML=`Рекомендуемая категория для этого типа: <strong>${cat}</strong>. Проверьте и отметьте нужный допуск.`}else{hint.textContent='Проверьте требуемую категорию допуска.'}}}
  type.addEventListener('change',update);update();
  form.addEventListener('submit',e=>{if(type.value!=='trailer'){if(!fuel?.value){e.preventDefault();e.stopImmediatePropagation();cfToast('Выберите тип топлива.','error');fuel?.focus();return}if(!(Number(norm?.value)>0)){e.preventDefault();e.stopImmediatePropagation();cfToast('Укажите норму расхода топлива.','error');norm?.focus();return}}},true);
}
function hydrateDriverCreate(form){if(!form||form.dataset.cfPatch)return;form.dataset.cfPatch=CF_VERSION;form.addEventListener('submit',e=>{const checked=form.querySelectorAll('input[name="categories"]:checked');if(!checked.length){e.preventDefault();e.stopImmediatePropagation();cfToast('Выберите хотя бы одну категорию водительского удостоверения.','error');form.querySelector('input[name="categories"]')?.focus()}},true)}
let cfPending=false;function cfScan(){cfPending=false;hydrateVehicleCreate(document.getElementById('vehicleCreateForm'));hydrateDriverCreate(document.getElementById('driverCreateForm'))}function cfSchedule(){if(cfPending)return;cfPending=true;queueMicrotask(cfScan)}new MutationObserver(cfSchedule).observe(document.documentElement,{childList:true,subtree:true});cfSchedule();
